mapper.sql:
FROM latest l INNER JOIN previous p ON p.barcode = l.barcode OUTER APPLY ( SELECT TOP 1 prod.DefaultSupplierGUID, prod.[Name] AS nameChinese, prod.NameP AS nameForeign FROM dbo.Products prod WHERE LTRIM(RTRIM(ISNULL(prod.Barcode, ''))) = l.barcode ORDER BY prod.UpdateTime DESC, prod.GUID DESC ) productRow LEFT JOIN dbo.Suppliers s ON s.GUID = productRow.DefaultSupplierGUID WHERE ROUND(p.previousPrice, 2) > 0 AND ROUND(l.latestPrice, 2) > ROUND(p.previousPrice, 2) AND (ROUND(l.latestPrice, 2) - ROUND(p.previousPrice, 2)) >= #{minChangeAmount}
AND l.barcode LIKE '%' + #{barcode} + '%'
AND ( COALESCE(NULLIF(LTRIM(RTRIM(s.[Name])), ''), NULLIF(LTRIM(RTRIM(s.NameP)), '')) LIKE '%' + #{supplierName} + '%' )
AND l.latestPurchaseDate >= #{fromPurchaseDate}
AND l.latestPurchaseDate < DATEADD(day, 1, CAST(#{toPurchaseDate} AS DATE))

mapper.select:
WITH ranked AS ( SELECT LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) AS barcode, pu.[DateTime] AS purchaseDate, COALESCE(NULLIF(LTRIM(RTRIM(s.[Name])), ''), NULLIF(LTRIM(RTRIM(s.NameP)), '')) AS supplierName, ROW_NUMBER() OVER ( PARTITION BY LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) ORDER BY pu.[DateTime] DESC, pd.[No] DESC ) AS rn FROM dbo.PurchaseDetails pd INNER JOIN dbo.Purchases pu ON pu.GUID = pd.MasterGUID LEFT JOIN dbo.Suppliers s ON s.GUID = pu.SupplierGUID WHERE LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) <> '' AND LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) IN
#{barcode}
) SELECT barcode, purchaseDate, supplierName FROM ranked WHERE rn = 1

WITH ranked AS ( SELECT LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) AS barcode, pu.[DateTime] AS purchaseDate, COALESCE(NULLIF(LTRIM(RTRIM(s.[Name])), ''), NULLIF(LTRIM(RTRIM(s.NameP)), '')) AS supplierName, ROW_NUMBER() OVER ( PARTITION BY LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) ORDER BY pu.[DateTime] DESC, pd.[No] DESC ) AS rn FROM dbo.PurchaseDetails pd INNER JOIN dbo.Purchases pu ON pu.GUID = pd.MasterGUID LEFT JOIN dbo.Suppliers s ON s.GUID = pu.SupplierGUID WHERE LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) <> '' AND pd.Quantity IS NOT NULL AND pd.CheckQuantity IS NOT NULL AND pd.CheckQuantity = pd.Quantity AND LTRIM(RTRIM(ISNULL(pd.Barcode, ''))) IN
#{barcode}
) SELECT barcode, purchaseDate, supplierName FROM ranked WHERE rn = 1
